// Configuração do projeto e termos curados para coleta de tendências.
// Defina projectId e adicione termos de busca (máximo 10 por execução para respeitar a cota).
return [{
  json: {
    projectId: "",
    queries: []
  }
}];

const now = new Date();
const observedAt = now.toISOString();
const windowEnd = observedAt;
const windowStart = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString();

const items = [];
for (const entry of $input.all()) {
  const searchResult = entry.json;
  const query = searchResult.query || 'ADE Lineup 2026';
  const rawItems = searchResult.items || [];

  if (rawItems.length === 0) continue;

  const evidence = [];
  let totalViews = 0;
  for (const raw of rawItems.slice(0, 5)) {
    const snippet = raw.snippet || {};
    const videoId = (raw.id && raw.id.videoId) ? raw.id.videoId : '';
    if (!videoId) continue;

    evidence.push({
      title: (snippet.title || 'Vídeo').slice(0, 200),
      url: 'https://youtube.com/watch?v=' + videoId,
      channel: (snippet.channelTitle || '').slice(0, 100),
      views: null,
      published_at: snippet.publishedAt || null
    });
  }

  if (evidence.length > 0) {
    items.push({
      topic: query.slice(0, 300),
      source_name: 'YouTube Data API',
      source_url: 'https://www.googleapis.com/youtube/v3/search',
      observed_at: observedAt,
      window_start: windowStart,
      window_end: windowEnd,
      metric_name: 'search_relevance',
      metric_value: 1.0,
      evidence: evidence
    });
  }
}

const cfg = $('Project Queries').first().json;
if (!cfg.projectId || items.length === 0) {
  return [];
}

return [{
  json: {
    project_id: cfg.projectId,
    items: items
  }
}];
